     1	// Mandatory guardrails for prod stacks (framework layer 5; they compensate OD8, where the stack's
     2	// owners, not the L3 owner team, approve IAM and stateful changes inside domain files).
     3	// Phase 2. Run by `pulumi up --policy-pack` in deploy-prod.yml; "a violation of a mandatory
     4	// policy stops the deployment" (R4.2.2). Exported separately from index.ts so that tests can
     5	// call the checks without the Pulumi engine.
     6	//
     7	// Limits (examples/README.md, E10):
     8	// - A value that is unknown during preview (e.g. a policy document built with
     9	//   pulumi.jsonStringify from a resource created in the same update) makes @pulumi/policy 1.21.0
    10	//   report the check as advisory during preview (✅ server.js). The update should then stop at
    11	//   that resource once the value is known (⚠️ not run here), after earlier resources in the same
    12	//   update may already exist. Access Analyzer (layer 5) is the preview-time check for IAM.
    13	// - Only resources declared in the stack are checked: a customer-managed policy created outside
    14	//   Pulumi and attached here by ARN is checked by name only (admin-equivalent AWS policies).
    15	import * as aws from "@pulumi/aws";
    16	import { ReportViolation, ResourceValidationPolicy, validateResourceOfType } from "@pulumi/policy";
    17	
    18	type Statement = { Effect?: string; Action?: string | string[]; NotAction?: string | string[] };
    19	
    20	function statementsOf(policy: unknown): Statement[] {
    21	    if (policy === undefined || policy === null) return [];
    22	    const doc = typeof policy === "string" ? JSON.parse(policy) : policy;
    23	    const st = (doc as { Statement?: Statement | Statement[] }).Statement ?? [];
    24	    return Array.isArray(st) ? st : [st];
    25	}
    26	
    27	// Services where any wildcard in the action name grants privilege escalation or identity changes,
    28	// e.g. iam:Pass*, iam:*Role*, sts:Assume*.
    29	const NO_WILDCARD_SERVICES = /^(iam|sts|organizations|sso|identitystore):/i;
    30	
    31	function wildcardActions(policy: unknown): string[] {
    32	    const found: string[] = [];
    33	    for (const st of statementsOf(policy)) {
    34	        if (st.Effect !== "Allow") continue;
    35	        if (st.NotAction !== undefined) found.push("NotAction");
    36	        const actions = st.Action === undefined ? [] : Array.isArray(st.Action) ? st.Action : [st.Action];
    37	        for (const a of actions) {
    38	            // IAM accepts `*` and `?` in action names (📖 IAM JSON policy elements: Action), so
    39	            // `*?`, `s3:?*` or `ec2:**` mean the same as `*` / `<service>:*`.
    40	            if (/^[*?]+$/.test(a) || /^[a-z0-9-]+:[*?]+$/i.test(a)) found.push(a);
    41	            else if (NO_WILDCARD_SERVICES.test(a) && /[*?]/.test(a)) found.push(a);
    42	        }
    43	    }
    44	    return found;
    45	}
    46	
    47	function report(actions: string[], reportViolation: ReportViolation) {
    48	    if (actions.length > 0) {
    49	        reportViolation(`IAM Allow with a wildcard action (${actions.join(", ")}); name the actions.`);
    50	    }
    51	}
    52	
    53	// AWS managed policies that grant `*` or `<service>:*`: the same grants iam-no-wildcard-actions
    54	// refuses in an inline or customer-managed document. Matched on any partition and path.
    55	function adminEquivalent(arn: unknown): boolean {
    56	    if (typeof arn !== "string") return false;
    57	    const m = /^arn:aws[a-z-]*:iam::aws:policy\/(?:.*\/)?([^/]+)$/.exec(arn);
    58	    return m !== null && (["AdministratorAccess", "PowerUserAccess"].includes(m[1]) || m[1].endsWith("FullAccess"));
    59	}
    60	
    61	function reportArns(arns: unknown, reportViolation: ReportViolation) {
    62	    const bad = ([] as unknown[]).concat(arns ?? []).filter(adminEquivalent);
    63	    if (bad.length > 0) {
    64	        reportViolation(`Attaches an admin-equivalent AWS managed policy (${bad.join(", ")}); write a scoped policy.`);
    65	    }
    66	}
    67	
    68	export const policies: ResourceValidationPolicy[] = [
    69	    {
    70	        name: "iam-no-wildcard-actions",
    71	        description: "IAM policies may not allow `*`, `<service>:*`, wildcards in iam/sts/organizations/sso " +
    72	            "actions, or use NotAction with Allow.",
    73	        enforcementLevel: "mandatory",
    74	        validateResource: [
    75	            validateResourceOfType(aws.iam.Policy, (p, _args, v) => report(wildcardActions(p.policy), v)),
    76	            validateResourceOfType(aws.iam.RolePolicy, (p, _args, v) => report(wildcardActions(p.policy), v)),
    77	            validateResourceOfType(aws.iam.UserPolicy, (p, _args, v) => report(wildcardActions(p.policy), v)),
    78	            validateResourceOfType(aws.iam.GroupPolicy, (p, _args, v) => report(wildcardActions(p.policy), v)),
    79	            validateResourceOfType(aws.iam.Role, (r, _args, v) => {
    80	                for (const inline of r.inlinePolicies ?? []) report(wildcardActions(inline.policy), v);
    81	            }),
    82	        ],
    83	    },
    84	    {
    85	        name: "iam-no-admin-managed-policies",
    86	        description: "No attachment of AdministratorAccess, PowerUserAccess or any AWS managed *FullAccess policy.",
